{
  "description": "Provides current economic inflation data for 38 major countries. The stats are usually updated monthly, although certain countries may lag behind or update more infrequently.",
  "required_parameters": [],
  "optional_parameters": [
    {
      "name": "type",
      "type": "String",
      "description": "Inflation indicator type. Can be either CPI (Consumer Price Index) or HICP (Harmonized Index of Consumer Prices). If not provided, CPI will be used by default.",
      "default": "CPI"
    }
  ]
}

