API_name: get_timezone_info
Description:
{
  "description": "Provides time zone information, including UTC and DST offsets, for any specified point on land based on latitude, longitude, and an optional UNIX timestamp. Note: Accuracy is not guaranteed for historical timestamps due to potential changes in time zone boundaries.",
  "required_parameters": [
    {
      "name": "lat",
      "type": "Number",
      "description": "The latitude component of any point on land."
    },
    {
      "name": "lng",
      "type": "Number",
      "description": "The longitude component of any point on land."
    }
  ],
  "optional_parameters": [
    {
      "name": "timestamp",
      "type": "Number",
      "description": "The UNIX timestamp at which the UTC and DST offsets will be calculated. Defaults to the present time."
    }
  ]
}

